import { randomUUID } from "node:crypto";

let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const id = input.documentId ?? randomUUID();
const timestamp = input.timestamp ?? new Date().toISOString();
const key = input.idempotencyKey ?? null;
const vendorStatus = input.vendorStatus ?? 200;
const headers = { "content-type": "application/json" };
const doc = { id, title: input.title, createdAt: timestamp };

const out = (http, rest = {}) => ({
  http,
  database: { rows: [], transaction: { committed: false, rolledBack: false } },
  messages: [],
  outbound: [],
  ordering: [],
  failures: [],
  retryability: false,
  ...rest,
});

let result;
const replay = input.replay === true || Number(input.attempt ?? 1) > 1 || input.existing != null;

if (typeof input.title !== "string" || input.title.trim() === "") {
  result = out(
    { status: 400, headers, body: { error: "invalid_title" } },
    { failures: [{ type: "validation", field: "title" }] }
  );
} else if (replay) {
  const existing = input.existing ?? doc;
  result = out(
    { status: 200, headers: { ...headers, "idempotent-replay": "true" }, body: { id: existing.id, title: existing.title, createdAt: existing.createdAt } },
    {
      database: { rows: [existing], transaction: { committed: false, rolledBack: false } },
      ordering: ["replay"],
    }
  );
} else {
  const authorize = { target: "vendor", step: "authorize", documentId: id, timestamp, idempotencyKey: key, status: vendorStatus };
  const outbound = [authorize];
  const ordering = ["vendor.authorize"];
  if (vendorStatus >= 200 && vendorStatus < 300) {
    outbound.push({ target: "vendor", step: "index", documentId: id, timestamp, idempotencyKey: key, status: vendorStatus });
    ordering.push("vendor.index", "db.commit", "event.emit");
    result = out(
      { status: 201, headers, body: doc },
      {
        database: { rows: [{ ...doc, idempotencyKey: key }], transaction: { committed: true, rolledBack: false } },
        messages: [{ type: "document.created", documentId: id, title: input.title, timestamp, idempotencyKey: key }],
        outbound,
        ordering,
      }
    );
  } else {
    const retryable = vendorStatus >= 500 || vendorStatus === 429 || vendorStatus === 408;
    const status = vendorStatus === 401 || vendorStatus === 403 ? 502 : retryable ? 503 : 502;
    result = out(
      { status, headers, body: { error: "vendor_failure", vendorStatus } },
      {
        outbound,
        ordering,
        failures: [{ type: "vendor", vendorStatus, mappedStatus: status }],
        retryability: retryable,
      }
    );
  }
}

console.log(JSON.stringify(result));

