  http,
  database: {
    rows: [],
    idempotency: { key, replayed: false },
    transaction: { committed: false, rollsBackOnFailure: true },
  },
  messages: [],
  outbound: [],
  ordering: [],
  failures: [],
  retryability: false,
  ...rest,
});

let result;
const replay = input.replay === true || Number(input.attempt ?? 1) > 1 || input.existing != null;

